-- ============================================================
-- CREATE TABLE cyber_abilities
-- ============================================================

CREATE TABLE public.cyber_abilities (
  id           uuid        NOT NULL DEFAULT gen_random_uuid(),
  name         text        NOT NULL,
  description  text        NULL,
  ability_type text        NULL,
  source       text        NULL,
  gm_notes     text        NULL,
  cost         text        NULL,
  img_url      text        NULL,
  tags         jsonb       NULL DEFAULT '[]'::jsonb,
  created_at   timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT cyber_abilities_pkey PRIMARY KEY (id)
);

